16	/** The active planning session's spec: the approval bar and the plan view. */
17	export type PlanState = {
18	  /** Workspace-relative path of the spec file. */
19	  specPath: string
20	  /** `implemented` is derived from the task markers, not held in the front matter. */
21	  status: 'missing' | 'draft' | 'approved' | 'implemented'
22	  /** Spec markdown without its front matter; absent while no spec is written. */
23	  body?: string
24	  /** A code check can be started from here: a plan session with a draft spec and no check running. */
25	  checkable: boolean
26	  /** The check run under this plan session: what it is doing, or how the last one ended. Absent before the first. */
27	  check?: CheckState
28	  /** Implementation can be started from here: a plan session with an approved spec. */
29	  implementable: boolean
30	  /** The plan's items by id, what a comment or a strike is attached to. */
31	  items: PlanItem[]
32	  /** Comments, strikes and resolutions so far; kept after approval as the record of how the plan was reached. */
33	  review: Review
34	  /** Comments can be attached: the artifact is a draft. */
35	  commentable: boolean
36	  /** No comment is open, so the plan may be approved. */
37	  approvable: boolean
38	  /** Amendments to product intent this feature settled; absent when none were proposed. */
