1	import type { SDKMessage } from '@anthropic-ai/claude-agent-sdk'
2	import type { SessionEvent, TurnUsage } from '../session/code-session'
3	
4	/**
5	 * Turns the Agent SDK's message stream into SessionEvents.
6	 *
7	 * Stateful because streaming deltas do not carry the message id they belong
8	 * to; `message_start` does, and the mapper remembers it until the next one.
9	 *
10	 * User messages are not mapped: the session emits `user_message` when it
11	 * sends, and replays on resume are restored from the run log instead.
12	 */
13	export class SdkEventMapper {
14	  private currentMessageId = ''
15	
16	  map(msg: SDKMessage): SessionEvent[] {
17	    switch (msg.type) {
18	      case 'system':
19	        return this.mapSystem(msg)
20	      case 'stream_event':
21	        return this.mapStreamEvent(msg)
22	      case 'assistant':
23	        return this.mapAssistant(msg)
24	      case 'user':
25	        return this.mapUser(msg)
26	      case 'result':
27	        return this.mapResult(msg)
28	      case 'auth_status':
29	        return msg.error ? [{ type: 'error', message: `Authentication: ${msg.error}`, fatal: false }] : []
30	      default:
31	        return []
32	    }
33	  }
34	
35	  private mapSystem(msg: Extract<SDKMessage, { type: 'system' }>): SessionEvent[] {
36	    switch (msg.subtype) {
37	      case 'init':
38	        return [
39	          {
40	            type: 'session_started',
41	            engineSessionId: msg.session_id,
42	            model: msg.model,
43	            engineVersion: msg.claude_code_version,
44	          },
45	        ]
46	      case 'status':
47	        return [{ type: 'status', status: msg.status ?? 'idle' }]
48	      case 'compact_boundary':
49	        return [{ type: 'status', status: 'idle' }]
50	      default:
51	        return []
52	    }
53	  }
54	
55	  private mapStreamEvent(msg: Extract<SDKMessage, { type: 'stream_event' }>): SessionEvent[] {
56	    const event = msg.event
57	    const parent = parentOf(msg.parent_tool_use_id)
58	    if (event.type === 'message_start') {
59	      this.currentMessageId = event.message.id
60	      return []
61	    }
62	    if (event.type !== 'content_block_delta') return []
63	    const messageId = this.currentMessageId
64	    if (event.delta.type === 'text_delta') {
65	      return [{ type: 'assistant_text', messageId, delta: event.delta.text, ...parent }]
66	    }
67	    if (event.delta.type === 'thinking_delta') {
68	      return [{ type: 'assistant_thinking', messageId, delta: event.delta.thinking, ...parent }]
69	    }
70	    return []
71	  }
72	
73	  private mapAssistant(msg: Extract<SDKMessage, { type: 'assistant' }>): SessionEvent[] {
74	    const parent = parentOf(msg.parent_tool_use_id)
75	    const events: SessionEvent[] = []
76	    if (msg.error) {
77	      events.push({ type: 'error', message: `Assistant error: ${msg.error}`, fatal: false })
78	    }
79	    const textParts: string[] = []
80	    for (const block of msg.message.content) {
81	      if (block.type === 'text') {
82	        textParts.push(block.text)
83	      } else if (block.type === 'tool_use') {
84	        events.push({ type: 'tool_call', toolUseId: block.id, name: block.name, input: block.input, ...parent })
85	      }
86	    }
87	    if (textParts.length > 0) {
88	      events.push({ type: 'assistant_message', messageId: msg.message.id, text: textParts.join(''), ...parent })
89	    }
90	    return events
91	  }
92	
93	  private mapUser(msg: Extract<SDKMessage, { type: 'user' }>): SessionEvent[] {
94	    if ('isReplay' in msg && msg.isReplay) return []
95	    const content = msg.message.content
96	    if (typeof content === 'string') return []
97	    const parent = parentOf(msg.parent_tool_use_id)
98	    const events: SessionEvent[] = []
99	    for (const block of content) {
100	      if (block.type !== 'tool_result') continue
101	      events.push({
102	        type: 'tool_result',
103	        toolUseId: block.tool_use_id,
104	        text: toolResultText(block.content),
105	        isError: block.is_error === true,
106	        ...parent,
107	      })
108	    }
109	    return events
110	  }
111	
112	  private mapResult(msg: Extract<SDKMessage, { type: 'result' }>): SessionEvent[] {
113	    const usage: TurnUsage = {
114	      inputTokens: msg.usage.input_tokens,
115	      outputTokens: msg.usage.output_tokens,
116	      cacheReadTokens: msg.usage.cache_read_input_tokens,
117	      cacheWriteTokens: msg.usage.cache_creation_input_tokens,
118	      costUsd: msg.total_cost_usd,
119	    }
120	    const errors = msg.subtype === 'success' ? [] : msg.errors
121	    if (msg.subtype !== 'success' && errors.length === 0) errors.push(msg.subtype)
122	    return [{ type: 'turn_done', usage, durationMs: msg.duration_ms, isError: msg.is_error, errors }]
123	  }
124	}
125	
126	function parentOf(parentToolUseId: string | null): { parentToolUseId?: string } {
127	  return parentToolUseId ? { parentToolUseId } : {}
128	}
129	
130	function toolResultText(content: unknown): string {
131	  if (content === undefined || content === null) return ''
132	  if (typeof content === 'string') return content
133	  if (Array.isArray(content)) {
134	    return content
135	      .map((part: unknown) => {
136	        if (typeof part === 'object' && part !== null && 'type' in part && part.type === 'text' && 'text' in part) {
137	          return String(part.text)
138	        }
139	        return `[${typeof part === 'object' && part !== null && 'type' in part ? String(part.type) : 'content'}]`
140	      })
141	      .join('\n')
142	  }
143	  return JSON.stringify(content)
144	}
