1	import type { CodeSession, PermissionDecision, SessionEvent, TurnUsage } from '../session/code-session'
2	import type { SessionHooks } from '../session/hooks'
3	import type { ModelProfile } from '../session/model-profile'
4	import { AsyncQueue } from '../session/async-queue'
5	import type { ChatCompletionClient, ChatMessage, ToolCall, Usage } from './chat-messages'
6	import { ReadTracker } from './tools/read-tracker'
7	import { toDefinition, type Tool, type ToolOutput } from './tools/tool'
8	
9	export type OpenAiSessionOptions = {
10	  id: string
11	  profile: ModelProfile
12	  cwd: string
13	  client: ChatCompletionClient
14	  tools: Tool[]
15	  systemPrompt: string
16	  hooks?: SessionHooks
17	  /** Tool rounds per user turn before the engine gives up; a runaway loop costs money. */
18	  maxRoundsPerTurn?: number
19	}
20	
21	/**
22	 * Our own agent loop over an OpenAI-compatible model: stream a completion,
23	 * run the tool calls it asked for, feed results back, repeat until it
24	 * answers without tools. Same events as the Claude engine.
25	 */
26	export class OpenAiSession implements CodeSession {
27	  readonly id: string
28	  readonly profile: ModelProfile
29	  private readonly output = new AsyncQueue<SessionEvent>()
30	  private readonly messages: ChatMessage[]
31	  private readonly queue: string[] = []
32	  private readonly files = new ReadTracker()
33	  private readonly pending = new Map<string, (d: PermissionDecision) => void>()
34	  private readonly definitions
35	  private turnAbort = new AbortController()
36	  private running = false
37	  private disposed = false
38	  private turnCounter = 0
39	
40	  constructor(private readonly options: OpenAiSessionOptions) {
41	    this.id = options.id
42	    this.profile = options.profile
43	    this.messages = [{ role: 'system', content: options.systemPrompt }]
44	    this.definitions = options.tools.map(toDefinition)
45	    this.output.push({ type: 'session_started', engineSessionId: options.id, model: options.profile.model })
46	  }
47	
48	  send(text: string): void {
49	    if (this.disposed) return
50	    this.output.push({ type: 'user_message', text })
51	    this.queue.push(text)
52	    if (!this.running) void this.drain()
53	  }
54	
55	  events(): AsyncIterable<SessionEvent> {
56	    return this.output
57	  }
58	
59	  respondToPermission(requestId: string, decision: PermissionDecision): void {
60	    const resolve = this.pending.get(requestId)
61	    if (!resolve) return
62	    this.pending.delete(requestId)
63	    this.output.push({ type: 'permission_resolved', requestId, decision: decision.kind })
64	    resolve(decision)
65	  }
66	
67	  async interrupt(): Promise<void> {
68	    this.turnAbort.abort()
69	    for (const [id, resolve] of this.pending) {
70	      this.pending.delete(id)
71	      resolve({ kind: 'deny', message: 'Interrupted' })
72	    }
73	  }
74	
75	  async dispose(): Promise<void> {
76	    if (this.disposed) return
77	    this.disposed = true
78	    await this.interrupt()
79	    this.output.push({ type: 'ended' })
80	    this.output.end()
81	  }
82	
83	  private async drain(): Promise<void> {
84	    this.running = true
85	    try {
86	      while (this.queue.length > 0 && !this.disposed) {
87	        const text = this.queue.shift()!
88	        this.messages.push({ role: 'user', content: text })
89	        await this.runTurn()
90	      }
91	    } finally {
92	      this.running = false
93	    }
94	  }
95	
96	  private async runTurn(): Promise<void> {
97	    this.turnAbort = new AbortController()
98	    const signal = this.turnAbort.signal
99	    const turn = ++this.turnCounter
100	    const usage: TurnUsage = { inputTokens: 0, outputTokens: 0, cacheReadTokens: 0, cacheWriteTokens: 0 }
101	    const started = Date.now()
102	    const maxRounds = this.options.maxRoundsPerTurn ?? 50
103	    try {
104	      for (let round = 1; ; round++) {
105	        if (round > maxRounds) {
106	          this.emitError(`Stopped after ${maxRounds} tool rounds in one turn`)
107	          return this.finishTurn(usage, started, true, ['max tool rounds'])
108	        }
109	        this.output.push({ type: 'status', status: 'requesting' })
110	        const assistant = await this.complete(`${turn}.${round}`, signal, usage)
111	        this.messages.push(assistant)
112	        if (assistant.toolCalls.length === 0) {
113	          const block = await this.verifyBeforeStop()
114	          if (block === undefined) return this.finishTurn(usage, started, false, [])
115	          this.messages.push({ role: 'user', content: block })
116	          continue
117	        }
118	        for (const call of assistant.toolCalls) {
119	          if (signal.aborted) throw new InterruptedError()
120	          const result = await this.runTool(call, signal)
121	          this.output.push({ type: 'tool_result', toolUseId: call.id, text: result.text, isError: result.isError })
122	          this.messages.push({ role: 'tool', toolCallId: call.id, content: result.text })
123	        }
124	        if (signal.aborted) throw new InterruptedError()
125	      }
126	    } catch (error) {
127	      this.repairAfterAbort()
128	      if (error instanceof InterruptedError || signal.aborted) {
129	        return this.finishTurn(usage, started, true, ['interrupted'])
130	      }
131	      const message = error instanceof Error ? error.message : String(error)
132	      this.emitError(message)
133	      return this.finishTurn(usage, started, true, [message])
134	    }
135	  }
136	
137	  /** Streams one completion, emitting deltas, and returns the assembled assistant message. */
138	  private async complete(
139	    messageId: string,
140	    signal: AbortSignal,
141	    usage: TurnUsage,
142	  ): Promise<Extract<ChatMessage, { role: 'assistant' }>> {
143	    let text = ''
144	    let reasoning = ''
145	    const calls = new Map<number, ToolCall>()
146	    for await (const delta of this.options.client.stream({
147	      model: this.options.profile.model,
148	      messages: this.messages,
149	      tools: this.definitions,
150	      signal,
151	    })) {
152	      switch (delta.type) {
153	        case 'text':
154	          text += delta.text
155	          this.output.push({ type: 'assistant_text', messageId, delta: delta.text })
156	          break
157	        case 'reasoning':
158	          reasoning += delta.text
159	          this.output.push({ type: 'assistant_thinking', messageId, delta: delta.text })
160	          break
161	        case 'tool_call_start':
162	          calls.set(delta.index, { id: delta.id, name: delta.name, arguments: '' })
163	          break
164	        case 'tool_call_arguments': {
165	          const call = calls.get(delta.index)
166	          if (call) call.arguments += delta.text
167	          break
168	        }
169	        case 'done':
170	          if (delta.usage) addUsage(usage, delta.usage)
171	          break
172	      }
173	    }
174	    if (text) this.output.push({ type: 'assistant_message', messageId, text })
175	    const toolCalls = [...calls.entries()].sort((a, b) => a[0] - b[0]).map(([, c]) => c)
176	    for (const call of toolCalls) {
177	      this.output.push({
178	        type: 'tool_call',
179	        toolUseId: call.id,
180	        name: call.name,
181	        input: parseArguments(call.arguments) ?? call.arguments,
182	      })
183	    }
184	    return { role: 'assistant', content: text, ...(reasoning ? { reasoning } : {}), toolCalls }
185	  }
186	
187	  private async runTool(call: ToolCall, signal: AbortSignal): Promise<ToolOutput> {
188	    const tool = this.options.tools.find((t) => t.name === call.name)
189	    if (!tool) return { text: `Unknown tool: ${call.name}`, isError: true }
190	    const raw = parseArguments(call.arguments)
191	    if (raw === undefined) return { text: `Tool arguments are not valid JSON: ${call.arguments.slice(0, 200)}`, isError: true }
192	    const parsed = tool.schema.safeParse(raw)
193	    if (!parsed.success) {
194	      const issues = parsed.error.issues.map((i) => `${i.path.join('.') || '(root)'}: ${i.message}`).join('; ')
195	      return { text: `Invalid arguments for ${tool.name}: ${issues}`, isError: true }
196	    }
197	    const use = { toolName: tool.name, input: parsed.data, toolUseId: call.id }
198	    const pre = await this.options.hooks?.preToolUse?.(use)
199	    if (pre && 'deny' in pre) return { text: `Blocked: ${pre.deny}`, isError: true }
200	    if (!tool.readOnly && !pre?.allow) {
201	      const decision = await this.askPermission(call.id, tool.name, parsed.data, signal)
202	      if (decision.kind === 'deny') return { text: `Denied by user${decision.message ? `: ${decision.message}` : ''}`, isError: true }
203	    }
204	    let output: ToolOutput
205	    try {
206	      output = await tool.execute(parsed.data, { cwd: this.options.cwd, signal, files: this.files })
207	    } catch (error) {
208	      output = { text: `${tool.name} failed: ${error instanceof Error ? error.message : String(error)}`, isError: true }
209	    }
210	    const post = await this.options.hooks?.postToolUse?.({ ...use, output: output.text, isError: output.isError })
211	    const context = [pre?.additionalContext, post?.additionalContext].filter((c): c is string => !!c)
212	    return context.length ? { ...output, text: `${output.text}\n\n${context.join('\n\n')}` } : output
213	  }
214	
215	  /** Runs the stop hook; returns the text to continue with, or undefined when the turn may end. */
216	  private async verifyBeforeStop(): Promise<string | undefined> {
217	    const stop = this.options.hooks?.stop
218	    if (!stop) return undefined
219	    this.output.push({ type: 'status', status: 'verifying' })
220	    const outcome = await stop((started) => this.output.push({ type: 'verification_started', ...started }))
221	    for (const v of outcome?.verifications ?? []) this.output.push({ type: 'verification', ...v })
222	    return outcome?.block
223	  }
224	
225	  private askPermission(requestId: string, toolName: string, input: unknown, signal: AbortSignal): Promise<PermissionDecision> {
226	    return new Promise((resolve) => {
227	      this.pending.set(requestId, resolve)
228	      signal.addEventListener('abort', () => {
229	        if (this.pending.delete(requestId)) resolve({ kind: 'deny', message: 'Interrupted' })
230	      })
231	      this.output.push({ type: 'permission_request', requestId, toolName, input })
232	    })
233	  }
234	
235	  /**
236	   * An assistant message with tool calls must be answered before the next
237	   * user message, or the API rejects the history. After an abort, whatever
238	   * calls are still unanswered get a synthetic result.
239	   */
240	  private repairAfterAbort(): void {
241	    const last = this.messages[this.messages.length - 1]
242	    if (!last || last.role !== 'assistant') return
243	    const answered = new Set<string>()
244	    for (let i = this.messages.length - 1; i >= 0; i--) {
245	      const m = this.messages[i]!
246	      if (m.role === 'tool') answered.add(m.toolCallId)
247	      else break
248	    }
249	    for (const call of last.toolCalls) {
250	      if (!answered.has(call.id)) this.messages.push({ role: 'tool', toolCallId: call.id, content: '[interrupted before this tool ran]' })
251	    }
252	  }
253	
254	  private finishTurn(usage: TurnUsage, started: number, isError: boolean, errors: string[]): void {
255	    this.output.push({ type: 'status', status: 'idle' })
256	    this.output.push({ type: 'turn_done', usage, durationMs: Date.now() - started, isError, errors })
257	  }
258	
259	  private emitError(message: string): void {
260	    this.output.push({ type: 'error', message, fatal: false })
261	  }
262	}
263	
264	class InterruptedError extends Error {
265	  constructor() {
266	    super('interrupted')
267	  }
268	}
269	
270	function addUsage(total: TurnUsage, usage: Usage): void {
271	  total.inputTokens += usage.promptTokens - usage.cachedTokens
272	  total.cacheReadTokens += usage.cachedTokens
273	  total.outputTokens += usage.completionTokens
274	}
275	
276	function parseArguments(text: string): unknown {
277	  if (text.trim() === '') return {}
278	  try {
279	    return JSON.parse(text)
280	  } catch {
281	    return undefined
282	  }
283	}
