/**
 * A line diff in unified form, with no dependency on the editor or the DOM:
 * the extension builds it from content it read itself, the webview only
 * renders what it is given.
 */

/** One line of the comparison, with where it sits on each side (0-based). */
type Op = { kind: 'equal' | 'del' | 'add'; aIndex: number; bIndex: number; text: string }

/**
 * Above this many cells the line-by-line table is not worth building; the
 * changed region is then reported as a whole-block replacement, which is what
 * a rewritten file looks like anyway.
 */
const MAX_CELLS = 4_000_000

export type DiffStats = { added: number; removed: number }

/** Text as lines, without the empty tail a trailing newline would produce. */
export function splitLines(text: string): string[] {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * The unified diff of `before` against `after`, `context` lines of context on
 * each side of a change. No file header: the step already says which file it
 * is, and the line budget is better spent on changed lines.
 */
export function unifiedDiff(before: string, after: string, context = 3): string[] {
  const ops = diffOps(splitLines(before), splitLines(after))
  const keep = ops.map(() => false)
  ops.forEach((op, i) => {
    if (op.kind === 'equal') return
    for (let k = Math.max(0, i - context); k <= Math.min(ops.length - 1, i + context); k++) keep[k] = true
  })
  const lines: string[] = []
  for (let i = 0; i < ops.length; ) {
    if (!keep[i]) {
      i++
      continue
    }
    let end = i
    while (end < ops.length && keep[end]) end++
    const hunk = ops.slice(i, end)
    lines.push(hunkHeader(hunk))
    for (const op of hunk) lines.push(`${marker(op.kind)}${op.text}`)
    i = end
  }
  return lines
}

export function diffStats(before: string, after: string): DiffStats {
  let added = 0
  let removed = 0
  for (const op of diffOps(splitLines(before), splitLines(after))) {
    if (op.kind === 'add') added++
    if (op.kind === 'del') removed++
  }
  return { added, removed }
}

/**
 * Where the first change lands in the file as it now is, 1-based: where the
 * step's own line is, so opening the file puts the cursor on the change.
 */
export function firstChangedLine(before: string, after: string): number | undefined {
  const op = diffOps(splitLines(before), splitLines(after)).find((o) => o.kind !== 'equal')
  return op ? Math.max(1, op.bIndex + 1) : undefined
}

function marker(kind: Op['kind']): string {
  return kind === 'add' ? '+' : kind === 'del' ? '-' : ' '
}

function hunkHeader(hunk: Op[]): string {
  const a = hunk.filter((o) => o.kind !== 'add')
  const b = hunk.filter((o) => o.kind !== 'del')
  // A hunk that only adds has no line of its own on the left; it sits after
  // the lines before it, which is what a zero count says in unified form.
  const aStart = a.length > 0 ? a[0]!.aIndex + 1 : hunk[0]!.aIndex
  const bStart = b.length > 0 ? b[0]!.bIndex + 1 : hunk[0]!.bIndex
  return `@@ -${aStart},${a.length} +${bStart},${b.length} @@`
}

function diffOps(a: string[], b: string[]): Op[] {
  let prefix = 0
  while (prefix < a.length && prefix < b.length && a[prefix] === b[prefix]) prefix++
  let suffix = 0
  while (suffix < a.length - prefix && suffix < b.length - prefix && a[a.length - 1 - suffix] === b[b.length - 1 - suffix]) suffix++
  const ops: Op[] = []
  for (let i = 0; i < prefix; i++) ops.push({ kind: 'equal', aIndex: i, bIndex: i, text: a[i]! })
  ops.push(...middleOps(a.slice(prefix, a.length - suffix), b.slice(prefix, b.length - suffix), prefix))
  for (let i = 0; i < suffix; i++) {
    const aIndex = a.length - suffix + i
    ops.push({ kind: 'equal', aIndex, bIndex: b.length - suffix + i, text: a[aIndex]! })
  }
  return ops
}

/** The differing middle, by longest common subsequence; `offset` is where it starts on both sides. */
function middleOps(a: string[], b: string[], offset: number): Op[] {
  const dels = a.map((text, i) => ({ kind: 'del' as const, aIndex: offset + i, bIndex: offset, text }))
  const adds = b.map((text, i) => ({ kind: 'add' as const, aIndex: offset + a.length, bIndex: offset + i, text }))
  if (a.length === 0 || b.length === 0 || a.length * b.length > MAX_CELLS) return [...dels, ...adds]

  const n = a.length
  const m = b.length
  const width = m + 1
  const lcs = new Uint32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      lcs[i * width + j] =
        a[i] === b[j] ? lcs[(i + 1) * width + j + 1]! + 1 : Math.max(lcs[(i + 1) * width + j]!, lcs[i * width + j + 1]!)
    }
  }
  const ops: Op[] = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      ops.push({ kind: 'equal', aIndex: offset + i, bIndex: offset + j, text: a[i]! })
      i++
      j++
    } else if (lcs[(i + 1) * width + j]! >= lcs[i * width + j + 1]!) {
      ops.push({ kind: 'del', aIndex: offset + i, bIndex: offset + j, text: a[i]! })
      i++
    } else {
      ops.push({ kind: 'add', aIndex: offset + i, bIndex: offset + j, text: b[j]! })
      j++
    }
  }
  while (i < n) {
    ops.push({ kind: 'del', aIndex: offset + i, bIndex: offset + j, text: a[i]! })
    i++
  }
  while (j < m) {
    ops.push({ kind: 'add', aIndex: offset + i, bIndex: offset + j, text: b[j]! })
    j++
  }
  return ops
}

/**
 * A line diff in unified form, with no dependency on the editor or the DOM:
 * the extension builds it from content it read itself, the webview only
 * renders what it is given.
 */

/** One line of the comparison, with where it sits on each side (0-based). */
type Op = { kind: 'equal' | 'del' | 'add'; aIndex: number; bIndex: number; text: string }

/**
 * Above this many cells the line-by-line table is not worth building; the
 * changed region is then reported as a whole-block replacement, which is what
 * a rewritten file looks like anyway.
 */
const MAX_CELLS = 4_000_000

export type DiffStats = { added: number; removed: number }

/** Text as lines, without the empty tail a trailing newline would produce. */
export function splitLines(text: string): string[] {
  if (text === '') return []
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  return lines
}

/**
 * The unified diff of `before` against `after`, `context` lines of context on
 * each side of a change. No file header: the step already says which file it
 * is, and the line budget is better spent on changed lines.
 */
export function unifiedDiff(before: string, after: string, context = 3): string[] {
  const ops = diffOps(splitLines(before), splitLines(after))
  const keep = ops.map(() => false)
  ops.forEach((op, i) => {
    if (op.kind === 'equal') return
    for (let k = Math.max(0, i - context); k <= Math.min(ops.length - 1, i + context); k++) keep[k] = true
  })
  const lines: string[] = []
  for (let i = 0; i < ops.length; ) {
    if (!keep[i]) {
      i++
      continue
    }
    let end = i
    while (end < ops.length && keep[end]) end++
    const hunk = ops.slice(i, end)
    lines.push(hunkHeader(hunk))
    for (const op of hunk) lines.push(`${marker(op.kind)}${op.text}`)
    i = end
  }
  return lines
}

export function diffStats(before: string, after: string): DiffStats {
  let added = 0
  let removed = 0
  for (const op of diffOps(splitLines(before), splitLines(after))) {
    if (op.kind === 'add') added++
    if (op.kind === 'del') removed++
  }
  return { added, removed }
}

/**
 * Where the first change lands in the file as it now is, 1-based: where the
 * step's own line is, so opening the file puts the cursor on the change.
 */
export function firstChangedLine(before: string, after: string): number | undefined {
  const op = diffOps(splitLines(before), splitLines(after)).find((o) => o.kind !== 'equal')
  return op ? Math.max(1, op.bIndex + 1) : undefined
}

function marker(kind: Op['kind']): string {
  return kind === 'add' ? '+' : kind === 'del' ? '-' : ' '
}

function hunkHeader(hunk: Op[]): string {
  const a = hunk.filter((o) => o.kind !== 'add')
  const b = hunk.filter((o) => o.kind !== 'del')
  // A hunk that only adds has no line of its own on the left; it sits after
  // the lines before it, which is what a zero count says in unified form.
  const aStart = a.length > 0 ? a[0]!.aIndex + 1 : hunk[0]!.aIndex
  const bStart = b.length > 0 ? b[0]!.bIndex + 1 : hunk[0]!.bIndex
  return `@@ -${aStart},${a.length} +${bStart},${b.length} @@`
}

function diffOps(a: string[], b: string[]): Op[] {
  let prefix = 0
  while (prefix < a.length && prefix < b.length && a[prefix] === b[prefix]) prefix++
  let suffix = 0
  while (suffix < a.length - prefix && suffix < b.length - prefix && a[a.length - 1 - suffix] === b[b.length - 1 - suffix]) suffix++
  const ops: Op[] = []
  for (let i = 0; i < prefix; i++) ops.push({ kind: 'equal', aIndex: i, bIndex: i, text: a[i]! })
  ops.push(...middleOps(a.slice(prefix, a.length - suffix), b.slice(prefix, b.length - suffix), prefix))
  for (let i = 0; i < suffix; i++) {
    const aIndex = a.length - suffix + i
    ops.push({ kind: 'equal', aIndex, bIndex: b.length - suffix + i, text: a[aIndex]! })
  }
  return ops
}

/** The differing middle, by longest common subsequence; `offset` is where it starts on both sides. */
function middleOps(a: string[], b: string[], offset: number): Op[] {
  const dels = a.map((text, i) => ({ kind: 'del' as const, aIndex: offset + i, bIndex: offset, text }))
  const adds = b.map((text, i) => ({ kind: 'add' as const, aIndex: offset + a.length, bIndex: offset + i, text }))
  if (a.length === 0 || b.length === 0 || a.length * b.length > MAX_CELLS) return [...dels, ...adds]

  const n = a.length
  const m = b.length
  const width = m + 1
  const lcs = new Uint32Array((n + 1) * width)
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      lcs[i * width + j] =
        a[i] === b[j] ? lcs[(i + 1) * width + j + 1]! + 1 : Math.max(lcs[(i + 1) * width + j]!, lcs[i * width + j + 1]!)
    }
  }
  const ops: Op[] = []
  let i = 0
  let j = 0
  while (i < n && j < m) {
    if (a[i] === b[j]) {
      ops.push({ kind: 'equal', aIndex: offset + i, bIndex: offset + j, text: a[i]! })
      i++
      j++
    } else if (lcs[(i + 1) * width + j]! >= lcs[i * width + j + 1]!) {
      ops.push({ kind: 'del', aIndex: offset + i, bIndex: offset + j, text: a[i]! })
      i++
    } else {
      ops.push({ kind: 'add', aIndex: offset + i, bIndex: offset + j, text: b[j]! })
      j++
    }
  }
  while (i < n) {
    ops.push({ kind: 'del', aIndex: offset + i, bIndex: offset + j, text: a[i]! })
    i++
  }
  while (j < m) {
    ops.push({ kind: 'add', aIndex: offset + i, bIndex: offset + j, text: b[j]! })
    j++
  }
  return ops
}

import { diffStats, firstChangedLine, unifiedDiff } from './unified-diff'

/** Lines of diff one step may spend in the chat, however many edits it carries. */
export const DIFF_LINE_BUDGET = 15

/** Context around a change, so the budget goes on changed lines. */
export const DIFF_CONTEXT = 3

/**
 * What one file-edit step did to its file, as the transcript keeps it. Built
 * by the extension from content it read itself, capped to what the chat shows,
 * and written to the run log so a reload renders the same thing without
 * touching the file again.
 */
export type FileEditChange = {
  /** Absolute path of the file the step writes. */
  path: string
  /** The path as the chat shows it: workspace-relative where the file lies inside. */
  label: string
  /** One unified diff per edit in the step, in order, already capped. */
  diffs: string[]
  /** Diff lines the cap left out; 0 when the whole diff is shown. */
  omitted: number
  /** Said in place of a diff: nothing changed, or the content is not readable as text. */
  summary?: string
  /** 1-based line of the first change, for opening the file where it happened. */
  line?: number
  /** The pre-edit content, kept under the session's run directory for the full-edit view. */
  snapshot?: string
  added?: number
  removed?: number
}

export type FileEditChangeInput = {
  path: string
  label: string
  /**
   * The file's content at each edit boundary: before the first edit, then
   * after each edit in the step. Two entries are one edit.
   */
  states?: string[]
  /** Why there is nothing to diff: the content is not readable as text. */
  unreadable?: string
  snapshot?: string
}

/** The link on a truncated diff says what it is hiding and where the rest is. */
export function omittedNotice(omitted: number): string {
  return `${omitted} more diff line${omitted === 1 ? '' : 's'} — open the full edit`
}

/**
 * The step's change as the chat shows it. Content that cannot be read as text
 * and a write that changed nothing both end as a one-line summary: an empty
 * diff block says less than a sentence.
 */
export function fileEditChange(input: FileEditChangeInput): FileEditChange {
  const { path, label } = input
  if (input.unreadable !== undefined || !input.states || input.states.length < 2) {
    return { path, label, diffs: [], omitted: 0, summary: `${label}: ${input.unreadable ?? 'changed'}` }
  }
  const states = input.states
  const first = states[0]!
  const last = states[states.length - 1]!
  const stats = diffStats(first, last)
  if (stats.added === 0 && stats.removed === 0) {
    return { path, label, diffs: [], omitted: 0, summary: `${label}: no change` }
  }
  const full: string[][] = []
  for (let i = 1; i < states.length; i++) {
    const diff = unifiedDiff(states[i - 1]!, states[i]!, DIFF_CONTEXT)
    if (diff.length > 0) full.push(diff)
  }
  const capped = capDiffs(full, DIFF_LINE_BUDGET)
  const line = firstChangedLine(first, last)
  return {
    path,
    label,
    diffs: capped.diffs.map((d) => d.join('\n')),
    omitted: capped.omitted,
    ...(line !== undefined ? { line } : {}),
    ...(input.snapshot !== undefined ? { snapshot: input.snapshot } : {}),
    added: stats.added,
    removed: stats.removed,
  }
}

/**
 * The first `budget` lines of the step's diffs, whichever edit they belong to:
 * one step cannot flood the chat however many edits it carries.
 */
export function capDiffs(diffs: string[][], budget: number): { diffs: string[][]; omitted: number } {
  const total = diffs.reduce((sum, d) => sum + d.length, 0)
  if (total <= budget) return { diffs, omitted: 0 }
  const kept: string[][] = []
  let spent = 0
  for (const diff of diffs) {
    if (spent >= budget) break
    const room = budget - spent
    kept.push(diff.slice(0, room))
    spent += Math.min(room, diff.length)
  }
  return { diffs: kept, omitted: total - spent }
}

